int qid = 100;
struct msqid_ds status_buf;
int ret;

// Retrieve queue status (IPC_STAT)
ret = msgctl(qid, IPC_STAT, &status_buf);
if (ret == 0) {
    // Use status_buf fields, e.g., status_buf.msg_qnum
}

// Set queue attributes (IPC_SET)
status_buf.msg_perm.mode = 0600;
msgctl(qid, IPC_SET, &status_buf);

// Remove queue identifier (IPC_RMID)
// Note: buf is often ignored when op=IPC_RMID
if (msgctl(qid, IPC_RMID, NULL) == -1) {
    // Error check (EACCES/EPERM, EINVAL)
}
